import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(n + 1)]

    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        adj[u].append((v, w))
        adj[v].append((u, w))

    s = int(next(iterator))
    m = int(next(iterator))

    criminals = []
    for _ in range(m):
        criminals.append(int(next(iterator)))

    def bfs_distances(start_node):
        dist = [-1] * (n + 1)
        dist[start_node] = 0
        queue = deque([start_node])

        while queue:
            u = queue.popleft()
            for v, w in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + w
                    queue.append(v)
        return dist

    dist_policeman = bfs_distances(s)

    max_time = 0
    safe_subtrees = []

    for c in criminals:
        dist_criminal = bfs_distances(c)
        can_escape = False

        for v in range(1, n + 1):
            if dist_policeman[v] > dist_criminal[v]:
                can_escape = True
                break

        if can_escape:
            print("Terrorists win")
            return

        if dist_policeman[c] > max_time:
            max_time = dist_policeman[c]

    print(max_time)

if __name__ == "__main__":
    solve()
